TOP_STRIP_HEIGHT: int = 56
DEFAULT_LERP_MS: float = 250.0

RING_ORDER: Tuple[str, ...] = (
    "modeler-agent",
    "props-agent",
    "look-agent",
    "camera-agent",
)

AGENT_SPECS: Dict[str, Dict[str, Any]] = {
    "modeler-agent": {
