}

VALID_REC_TYPES = frozenset({"claim", "enqueue", "turn", "close", "cursor", "control"})
ENQUEUE_REFUSAL_VERDICTS = frozenset({"DUPLICATE_EVENT", "QUEUE_FULL"})

STANDING_CAPTION: str = (
