)

# Verdict classification palettes (RGBA) per CONTRACT.md Section 6
GREEN_VERDICTS = frozenset({"STATE_VERIFIED"})
CYAN_VERDICTS = frozenset({"VERIFIED", "VERIFIED_WITH_SPILL"})
AMBER_VERDICTS = frozenset(
    {
        "STALE_FRAME",
        "NO_VISIBLE_CHANGE",
        "TURN_TIMEOUT",
        "ACTUATOR_BUSY",
        "QUEUE_FULL",
        "DUPLICATE_EVENT",
    }
)
RED_VERDICTS = frozenset(
    {
        "CLAIM_REFUSED",
        "NO_LEASE",
        "LEASE_EXPIRED",
        "FRAME_EVICTED",
        "FOOTPRINT_MISSING",
        "JOB_ERROR",
        "INPUT_UNCERTAIN",
        "OUTCOME_UNCERTAIN",
    }
)


def parse_hex_rgb(color_str: Optional[str], fallback: Tuple[int, int, int]) -> Tuple[int, int, int]:
    """Parse `#rrggbb` hex color string into `(R, G, B)` tuple."""
    if not color_str or not isinstance(color_str, str):
        return fallback
    s = color_str.strip().lstrip("#")
    if len(s) == 6:
        try:
            return (int(s[0:2], 16), int(s[2:4], 16), int(s[4:6], 16))
        except ValueError:
            return fallback
    return fallback


def verdict_palette(verdict: Optional[str]) -> Tuple[Tuple[int, int, int, int], Tuple[int, int, int, int], Tuple[int, int, int, int], str]:
    """Return `(bg_rgba, border_rgba, text_rgba, symbol)` for a verdict code."""
    if not verdict or verdict == "PASS" or verdict == "STANDBY":
        return ((30, 41, 59, 232), (100, 116, 139, 225), (203, 213, 225, 255), "·")
    if verdict in GREEN_VERDICTS:
        return ((6, 78, 59, 245), (52, 211, 153, 255), (167, 243, 208, 255), "✓")
    if verdict in CYAN_VERDICTS:
        return ((8, 51, 68, 245), (34, 211, 238, 255), (165, 243, 252, 255), "✓")
    if verdict in AMBER_VERDICTS:
        return ((120, 53, 15, 245), (251, 191, 36, 255), (254, 240, 138, 255), "!")
    if verdict in RED_VERDICTS:
        return ((127, 29, 29, 245), (248, 113, 113, 255), (254, 202, 202, 255), "✗")
    return ((30, 41, 59, 235), (148, 163, 184, 235), (226, 232, 240, 255), "·")


@dataclass(frozen=True)
