class FontPack:
    """TrueType font loader with deterministic Linux system font fallbacks."""

    BOLD_CANDIDATES = (
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        "/usr/share/fonts/opentype/urw-base35/NimbusSans-Bold.otf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
    )
    REGULAR_CANDIDATES = (
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/opentype/urw-base35/NimbusSans-Regular.otf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
    )
    MONO_CANDIDATES = (
        "/usr/share/fonts/truetype/dejavu/DejaVuSansMono-Bold.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
    )

    def __init__(self, scale: float = 1.0) -> None:
        s = max(0.5, float(scale))
        self.strip_bold = self._load(self.BOLD_CANDIDATES, max(10, round(14 * s)))
        self.strip_small = self._load(self.BOLD_CANDIDATES, max(9, round(12 * s)))
        self.cursor_bold = self._load(self.BOLD_CANDIDATES, max(9, round(13 * s)))
        self.cursor_sub = self._load(self.REGULAR_CANDIDATES, max(8, round(11 * s)))
        self.caption = self._load(self.REGULAR_CANDIDATES, max(9, round(13 * s)))
        self.mono = self._load(self.MONO_CANDIDATES, max(9, round(12 * s)))

    @staticmethod
    def _load(candidates: Sequence[str], size: int) -> ImageFont.FreeTypeFont | ImageFont.ImageFont:
        for path in candidates:
            if os.path.isfile(path):
                try:
                    return ImageFont.truetype(path, size=size)
                except OSError:
                    continue
        try:
            return ImageFont.load_default(size=size)
        except TypeError:
            return ImageFont.load_default()


def probe_video(input_path: Path) -> VideoMeta:
    """Inspect input MP4 metadata via `ffprobe` with `cv2.VideoCapture` fallback."""
    width = 0
    height = 0
    fps = 15.0
    duration_ms = 0
    nb_frames = 0

    try:
        proc = subprocess.run(
            [
                "ffprobe",
                "-v",
                "error",
                "-select_streams",
                "v:0",
                "-show_entries",
                "stream=width,height,r_frame_rate,avg_frame_rate,nb_frames,duration:format=duration",
                "-of",
                "json",
                str(input_path),
            ],
            check=True,
            capture_output=True,
            text=True,
        )
        info = json.loads(proc.stdout)
        streams = info.get("streams") or []
        if streams:
            st = streams[0]
            width = int(st.get("width") or 0)
            height = int(st.get("height") or 0)
            fps = _parse_rate(st.get("avg_frame_rate")) or _parse_rate(st.get("r_frame_rate")) or 15.0
            if st.get("nb_frames") and str(st["nb_frames"]).isdigit():
                nb_frames = int(st["nb_frames"])
            if st.get("duration"):
                try:
                    duration_ms = int(round(float(st["duration"]) * 1000.0))
                except ValueError:
                    pass
        if duration_ms <= 0 and info.get("format", {}).get("duration"):
            try:
                duration_ms = int(round(float(info["format"]["duration"]) * 1000.0))
            except ValueError:
                pass
    except (subprocess.SubprocessError, json.JSONDecodeError, OSError):
        pass

    if width <= 0 or height <= 0 or duration_ms <= 0:
        cap = cv2.VideoCapture(str(input_path))
        if not cap.isOpened():
            raise RuntimeError(f"Unable to open input video: {input_path}")
        if width <= 0:
            width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
        if height <= 0:
            height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
        cap_fps = float(cap.get(cv2.CAP_PROP_FPS) or 0.0)
        if cap_fps > 0.1:
            fps = cap_fps
        cap_frames = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
        if nb_frames <= 0 and cap_frames > 0:
            nb_frames = cap_frames
        if duration_ms <= 0 and nb_frames > 0 and fps > 0:
            duration_ms = int(round((nb_frames / fps) * 1000.0))
        cap.release()

    if nb_frames <= 0 and duration_ms > 0:
        nb_frames = max(1, int(round((duration_ms / 1000.0) * fps)))
    if duration_ms <= 0:
        duration_ms = max(100, int(round((max(1, nb_frames) / max(1.0, fps)) * 1000.0)))

    return VideoMeta(
        width=width,
        height=height,
        fps=fps,
        duration_ms=duration_ms,
        nb_frames=max(1, nb_frames),
    )


def _parse_rate(rate_str: Optional[str]) -> Optional[float]:
    if not rate_str or not isinstance(rate_str, str):
        return None
    if "/" in rate_str:
        num_s, den_s = rate_str.split("/", 1)
        try:
            num = float(num_s)
            den = float(den_s)
            if den > 0 and num > 0:
                return num / den
        except ValueError:
            return None
    else:
        try:
            val = float(rate_str)
            return val if val > 0 else None
        except ValueError:
            return None
    return None


